[
  {
    "id": "ton_timer",
    "title": "Standard IEC TON Timer Block Invocation",
    "body": "// Standard IEC TON timer: MUST invoke unconditionally OUTSIDE CASE/IF every scan!\nVAR\n    timer : TON;\n    runTimer : BOOL;\nEND_VAR\n// Control via boolean IN flag (never put timer(...) only inside an IF/CASE arm):\nrunTimer := (state = 1) AND NOT resetCmd;\ntimer(IN := runTimer, PT := T#2s);\nIF timer.Q THEN\n    // Timer expired; timer.ET holds elapsed time\nEND_IF;"
  },
  {
    "id": "case_state_machine",
    "title": "Explicit CASE State Machine Transitions",
    "body": "// 4-Stage Scan Order: 1) Edge sample 2) Reset/priority & CASE state transition\n// 3) Unconditional top-level TON/R_TRIG calls 4) Unified output assignments\nVAR\n    state : INT := 0; // 0=IDLE, 1=RUN, 2=FAULT\nEND_VAR\nIF emergencyStop THEN state := 2; END_IF;\nCASE state OF\n    0: IF startCmd AND NOT fault THEN state := 1; END_IF;\n    1: IF faultCmd THEN state := 2; ELSIF stopCmd THEN state := 0; END_IF;\n    2: IF resetCmd THEN state := 0; END_IF;\n    ELSE state := 0;\nEND_CASE;\noutActive := (state = 1); // Assign outputs unconditionally from current state"
  }
]

{
  "declaration": "FUNCTION_BLOCK FB_Task
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    Fault : BOOL;
    Reset : BOOL;
END_VAR
VAR_OUTPUT
    Run : BOOL := FALSE;
    Locked : BOOL := FALSE;
    Attempts : USINT := 0;
END_VAR
VAR
    mode : E_Mode := E_Mode.IDLE;
    free_scans : USINT := 0;
    attempt_count : USINT := 0;
    validReset : BOOL;
    bStart : BOOL;
    bStop : BOOL;
    bFault : BOOL;
    bReset : BOOL;
END_VAR",
  "implementation": "// Stage 1: sample inputs once and derive valid reset
bStart := Start;
bStop := Stop;
bFault := Fault;
bReset := Reset;
validReset := bReset AND NOT bFault AND NOT bStart;

// Stage 2: priority transition using retained pre-state q[k]
IF validReset THEN
    mode := E_Mode.IDLE;
    attempt_count := 0;
    free_scans := 0;
ELSIF mode = E_Mode.LOCKED THEN
    // Latched lockout: remain LOCKED absent valid reset
    mode := E_Mode.LOCKED;
    free_scans := 0;
    // attempt_count preserved
ELSIF bStop THEN
    // Abort to IDLE without clearing retry count
    mode := E_Mode.IDLE;
    free_scans := 0;
    // attempt_count preserved
ELSE
    CASE mode OF
        E_Mode.IDLE:
            IF bStart AND NOT bFault THEN
                mode := E_Mode.RUNNING;
                free_scans := 0;
                // attempt_count preserved
            ELSE
                mode := E_Mode.IDLE;
                free_scans := 0;
                // attempt_count preserved
            END_IF;

        E_Mode.RUNNING:
            IF bFault THEN
                IF attempt_count >= 2 THEN
                    mode := E_Mode.LOCKED;
                    free_scans := 0;
                    // attempt_count preserved
                ELSE
                    mode := E_Mode.WAIT;
                    free_scans := 0;
                    // attempt_count preserved
                END_IF;
            ELSE
                mode := E_Mode.RUNNING;
                free_scans := 0;
                // attempt_count preserved
            END_IF;

        E_Mode.WAIT:
            IF bFault THEN
                mode := E_Mode.WAIT;
                free_scans := 0;
                // attempt_count preserved
            ELSIF free_scans >= 1 THEN
                // Second consecutive fault-free dwell scan: issue one retry
                IF attempt_count < 2 THEN
                    attempt_count := attempt_count + 1;
                END_IF;
                free_scans := 0;
                mode := E_Mode.RUNNING;
            ELSE
                // First fault-free dwell scan
                free_scans := free_scans + 1;
                mode := E_Mode.WAIT;
                // attempt_count preserved
            END_IF;

        E_Mode.LOCKED:
            // Defensive latch branch; normally handled before CASE
            mode := E_Mode.LOCKED;
            free_scans := 0;
            // attempt_count preserved

        ELSE
            mode := E_Mode.IDLE;
            free_scans := 0;
            // attempt_count preserved
    END_CASE;
END_IF;

// Stage 3: no timer FB calls for SELF012; recovery dwell is scan-count based

// Stage 4: unified output assignments from post-transition state
Run := (mode = E_Mode.RUNNING);
Locked := (mode = E_Mode.LOCKED);
Attempts := attempt_count;",
